Given an array of integers, the task is to delete an element from a given position in the array.Examples:Input: arr[] = [10, 20, 30, 40], pos = 1Output: [20, 30, 40]Input: arr[] = [10, 20, 30, 40], pos = 2Output: [10, 30, 40]Input: arr[] = [10, 20, 30, 40], pos = 4Output: [10, 20, 30]Table of Content[Approach 1] Using Built-In Methods[Approach 2] Using Custom Method[Approach 1] Using Built-In MethodsWe will use library methods like erase() in C++, remove() in Java, del in Python, removeAt() in C# and splice() in JavaScript.
            C++

    // C++ program to delete an element from a given  
// position in an array

#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> arr = { 10, 20, 30, 40 };
	int pos = 2;

    cout << "Array before deletion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

  	// Delete the element at the given position
    arr.erase(arr.begin() + pos - 1);

    cout << "\nArray after deletion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    return 0;
}


